"""Parity dichotomy: even hyperedges admit all-crossing states."""
from __future__ import annotations
from typing import Sequence

def cycle_chromatic_number(length: int) -> int:
    """Chromatic number of the boundary cycle C_length (length >= 3)."""
    if length < 3:
        raise ValueError("cycle needs length >= 3")
    return 2 if length % 2 == 0 else 3

def all_crossing_exists(hyperedge_lengths: Sequence[int]) -> bool:
    """An all-crossing direction exists iff every hyperedge has even length."""
    return all(l % 2 == 0 for l in hyperedge_lengths)

if __name__ == "__main__":
    for l in range(3, 10):
        print(f"C_{l}: chi = {cycle_chromatic_number(l)}  even? {l % 2 == 0}")
    print("lengths [4,6,8] ->", all_crossing_exists([4, 6, 8]))
    print("lengths [4,5,8] ->", all_crossing_exists([4, 5, 8]))

